const FLIP_MAP ={a: "ɐ", b: "q", c: "ɔ", d: "p", e: "ǝ", f: "ɟ", g: "ƃ", h: "ɥ", i: "ᴉ", j: "ɾ", k: "ʞ", l: "l", m: "ɯ", n: "u", o: "o", p: "d", q: "b", r: "ɹ", s: "s", t: "ʇ", u: "n", v: "ʌ", w: "ʍ", x: "x", y: "ʎ", z: "z", "0": "0", "1": "Ɩ", "2": "ᄅ", "3": "Ɛ", "4": "ㄣ", "5": "ϛ", "6": "9", "7": "ㄥ", "8": "8", "9": "6", ".": "˙", ",": "'", "'": ",", '"': ",,", "!": "¡", "?": "¿", "(": ")", ")": "(", "[": "]", "]": "[", "{": "}", "}": "{", "<": ">", ">": "<", "&": "⅋", "_": "‾", " ": " ",};function flipText(text){const unflippable = new Set();const flipped = Array.from(text) .map((ch) =>{const lower = ch.toLowerCase();if (FLIP_MAP[lower] === undefined){unflippable.add(ch);return ch;}return FLIP_MAP[lower];}) .reverse() .join("");return{flipped, unflippable: Array.from(unflippable)};}function executeUpsideDown(){const raw = document.getElementById("flip-input").value;const out = document.getElementById("flip-result");const warn = document.getElementById("flip-warning");if (!raw){GAMA.say("idle");out.textContent = "";warn.textContent = "";return;}const{flipped, unflippable}= flipText(raw);out.textContent = flipped;warn.textContent = unflippable.length ? `// no real flipped lookalike for: ${unflippable.join(" ")} - left as-is` : "";GAMA.say("success");}